import {CITIES} from './places.js';
import {esc} from './weather-tools.js';
const $=s=>document.querySelector(s),tags=['Leggero','A strati','Impermeabile','Ombrello','Scarpe chiuse'];
export function coarseArea(lat,lon){return {latitude:Math.round(lat*50)/50,longitude:(((Math.round(lon*50)+9000)%18000+18000)%18000-9000)/50}}
export function createFitCheck(ctx){
 let center=null,placeKey='',data=null,error='',busy=false,revision=0,map=null,mapRevision=0,radius=5,tag='',selected='',editing=false,mine=null,mineBusy=false,mineError='',draft={post:'',area:null,tag:'A strati'},pendingPost='',events=null,gpsRevision=0;
 const active=()=>ctx.get().route==='fitcheck';
 const age=t=>{const m=Math.max(0,Math.floor((Date.now()-t)/60000));return m<1?'appena pubblicato':m<60?m+' min fa':Math.floor(m/60)+' ore fa'};
 function sync(){const p=ctx.get().place,k=p.latitude+','+p.longitude;if(k!==placeKey){placeKey=k;center=coarseArea(p.latitude,p.longitude);revision++;data=null;error='';busy=false;selected=''}}
 const media=(p,small=false)=>p.video?`<video src="/api/network/video/${p.id}" controls playsinline muted preload="none" aria-label="${esc(p.text.slice(0,120))}" ${small?'class="fit-small"':''}></video>`:`<img src="/api/photo/${p.id}" loading="lazy" alt="${esc(p.text.slice(0,160))}">`;
 function cards(){if(error)return `<div class="fit-empty" role="alert"><h2>La community non si carica</h2><p>${esc(error)}</p><button data-fit-refresh>Riprova</button></div>`;if(!data)return '<p class="fit-empty" role="status">Cerco foto e video della zona…</p>';const posts=data.posts.filter(p=>p.expires>Date.now());return posts.length?`<div class="fit-cards">${posts.map(p=>`<article id="fit-post-${p.id}" class="fit-card ${selected===p.id?'is-selected':''}"><div class="fit-card-media">${media(p)}<span>${esc(p.tag)}</span></div><div class="fit-card-body"><a href="#persona:${p.author}" class="fit-author">${esc(p.name)}</a><p>${esc(p.text)}</p><small>${esc(p.city)} · ${age(p.created)}<br>≈ ${p.distance.toFixed(1)} km tra i centri delle zone</small><div class="fit-actions"><button data-fit-pin="${p.id}">Sulla mappa</button><a href="#post:${p.id}">Commenta e reagisci →</a></div>${p.author===ctx.get().me?.id?`<button class="fit-remove" data-fit-remove="${p.id}">Rimuovi dalla mappa</button>`:''}</div></article>`).join('')}</div>${data.limited?'<p>Mostriamo fino a 100 contributi recenti. Restringi la zona o scegli un filtro.</p>':''}`:`<div class="fit-empty"><span aria-hidden="true">↗</span><h2>Il primo consiglio può essere il tuo.</h2><p>Nessun Fit Check nelle ultime 24 ore ${tag?'con questo filtro ':''}entro ${radius} km. La mappa si popola con i contenuti condivisi dalle persone.</p><button data-fit-add>Aggiungi il tuo</button>${tag?'<button data-fit-clear>Tutti i consigli</button>':''}</div>`}
 function editor(){if(!editing)return '';const p=mine?.find(p=>p.id===draft.post);return `<section class="fit-editor" aria-labelledby="fit-editor-title"><div class="fit-editor-title"><h2 id="fit-editor-title">Il tuo consiglio, nella zona.</h2><button data-fit-cancel>Chiudi</button></div><p>Per le città riconosciute, la zona deve essere entro 35 km dalla località del post.</p><p>Usa una tua foto o un video recente per raccontare come ti vesti o affronti il tempo. Puoi contribuire da un posto sicuro.</p>${mineError?`<p role="alert">${esc(mineError)}</p><button data-fit-mine-retry>Riprova</button>`:mine===null?'<p role="status">Carico i tuoi contenuti…</p>':!mine.length?'<p>Serve una foto o un video pubblicato nelle ultime 24 ore.</p><a class="button" href="#studio">Crea una foto</a> <a href="#community">Carica un video nella Community</a>':`<form id="fit-publish-form"><label class="field"><span>1. Il contenuto</span><select id="fit-post" required><option value="">Scegli una foto o un video</option>${mine.map(p=>`<option value="${p.id}" ${draft.post===p.id?'selected':''}>${esc(p.city+' · '+p.text.slice(0,65))}</option>`).join('')}</select></label>${p?`<div class="fit-draft-media">${media(p,true)}</div>`:''}<label class="field"><span>2. Il consiglio</span><select id="fit-tag">${tags.map(t=>`<option ${draft.tag===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="fit-area-choice"><b>3. La zona da rendere pubblica</b><p id="fit-area-status" role="status">${draft.area?'Area scelta: '+draft.area.latitude.toFixed(2)+'°, '+draft.area.longitude.toFixed(2)+'°. Puoi cambiarla toccando la mappa.':'Tocca la mappa per scegliere una zona approssimata, oppure usa una delle opzioni qui sotto.'}</p><div class="fit-actions"><button type="button" data-fit-pick>Scegli sulla mappa ↓</button><button type="button" data-fit-current>Usa il centro della mappa</button><button type="button" data-fit-gps>Usa la mia zona</button></div></div><label class="fit-consent"><input id="fit-consent" type="checkbox" required> Ho controllato la zona e il contenuto: voglio rendere pubblico questo consiglio, senza indicare casa o dati personali.</label><p class="fit-note">La posizione viene approssimata prima dell’invio. La zona resta visibile fino a 24 ore dalla pubblicazione del post; puoi rimuoverla prima. Il contenuto originale resta nella community.</p><button class="button" id="fit-save">Pubblica sulla mappa</button><p id="fit-save-status" role="alert"></p></form>`}</section>`}
 function page(){sync();return `<section class="fit-workspace"><div class="fit-heading"><div><span class="eyebrow">IL METEO, INDOSSATO</span><h1>Come ci si veste<br>da queste parti?</h1><p>Guarda le persone. Capisci la zona.</p></div><button class="button" data-fit-add>＋ Il tuo Fit Check</button></div><div class="fit-links"><a href="#mappa">← Radar e mappa</a><a href="#community">Community</a><button data-fit-ai>Chiedi all’assistente ✧</button></div>${editor()}<div class="fit-layout"><div class="fit-map-column"><div class="fit-map-heading"><div><b>Area esplorata · ${center.latitude.toFixed(2)}°, ${center.longitude.toFixed(2)}°</b><small>I pin indicano aree, non indirizzi.</small></div><a href="#mappa">Cambia città</a></div><div id="fit-map" aria-label="Mappa delle zone dei Fit Check"></div><p id="fit-map-note" class="fit-note" role="status">${editing?'Tocca la mappa per posizionare il tuo consiglio.':'Tocca un numero per leggere i consigli di quella zona.'}</p><button data-fit-search-area>Cerca in quest’area</button><p class="fit-note">Coordinate dichiarate, non verificate. Celle di circa 2 km in latitudine, più strette verso i poli. I video non partono da soli.</p><div class="fit-weather-link"><span aria-hidden="true">☀</span><div><b>Il cielo cambia. Controlla anche le previsioni.</b><button data-fit-weather>Previsioni di quest’area →</button></div></div></div><div class="fit-feed-column"><div class="fit-filters"><label>Quanto vicino?<select id="fit-radius"><option value="5" ${radius===5?'selected':''}>Entro 5 km</option><option value="20" ${radius===20?'selected':''}>Entro 20 km</option></select></label><label>Consiglio<select id="fit-filter"><option value="">Tutti</option>${tags.map(t=>`<option ${tag===t?'selected':''}>${t}</option>`).join('')}</select></label><button data-fit-refresh aria-label="Aggiorna i Fit Check">↻</button></div><p class="fit-recency">Ultime 24 ore · orario di pubblicazione, non ripresa verificata</p><div id="fit-results">${cards()}</div></div></div></section>`}
 async function load(){if(busy)return;const token=++revision;busy=true;error='';try{const r=await ctx.api('fitcheck/feed?'+new URLSearchParams({...center,radius,tag}));if(token!==revision)return;data=r}catch(e){if(token===revision)error=e.message}finally{if(token===revision){busy=false;if(active())ctx.render()}}}
 async function loadMine(){if(mineBusy)return;mineBusy=true;const token=++gpsRevision;mineError='';try{const r=await ctx.api('fitcheck/mine');if(token!==gpsRevision)return;mine=r.posts;if(pendingPost){const p=mine.find(x=>x.id===pendingPost);pendingPost='';if(p)selectDraft(p.id)}}catch(e){if(token===gpsRevision)mineError=e.message}finally{mineBusy=false;if(token===gpsRevision&&active())ctx.render()}}
 function selectDraft(id){draft.post=id;const p=mine?.find(x=>x.id===id);draft.tag=p?.tag||'A strati';draft.area=p?.latitude!=null?coarseArea(p.latitude,p.longitude):null;const city=CITIES.find(c=>c.name.toLocaleLowerCase()===p?.city?.trim().toLocaleLowerCase());if(draft.area||city){center=draft.area||coarseArea(city.latitude,city.longitude);revision++;busy=false;data=null;error=''}}
 function area(p){draft.area=coarseArea(Math.max(-85,Math.min(85,p.latitude)),((p.longitude+180)%360+360)%360-180);const label=$('#fit-area-status');if(label)label.textContent='Area scelta: '+draft.area.latitude.toFixed(2)+'°, '+draft.area.longitude.toFixed(2)+'°. Controllala sulla mappa.';const consent=$('#fit-consent');if(consent)consent.checked=false;const note=$('#fit-map-note');if(note)note.innerHTML='Zona scelta. <a href="#fit-editor-title" id="fit-back-editor">Torna alla conferma ↑</a>';const back=$('#fit-back-editor');if(back)back.onclick=e=>{e.preventDefault();$('#fit-editor-title')?.scrollIntoView({block:'start'})};drawDraft()}
 let draftLayer=null;
 function drawDraft(){if(!map)return;if(draftLayer)map.removeLayer(draftLayer);draftLayer=null;if(editing&&draft.area&&map._fitL){const p=draft.area;draftLayer=map._fitL.rectangle([[p.latitude-.01,p.longitude-.01],[p.latitude+.01,p.longitude+.01]],{color:'#185bda',weight:3,fillOpacity:.15}).addTo(map)}}
 async function mount(){const host=$('#fit-map');if(!host)return;const token=++mapRevision;try{const L=await import('./assets/leaflet.js');if(token!==mapRevision||!host.isConnected)return;map=L.map(host,{scrollWheelZoom:false,maxZoom:15,minZoom:3,worldCopyJump:true}).setView([center.latitude,center.longitude],radius===5?12:10);map._fitL=L;let errors=0;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).on('tileerror',()=>{if(++errors===3&&$('#fit-map-note'))$('#fit-map-note').textContent='La cartografia non si carica. I consigli restano leggibili nell’elenco.'}).addTo(map);
  L.circle([center.latitude,center.longitude],{radius:radius*1000,color:'#64748b',weight:1,fillOpacity:.02,interactive:false}).addTo(map);
  const groups=new Map();for(const p of data?.posts||[]){if(p.expires<=Date.now())continue;const k=p.latitude+','+p.longitude;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(p)}
  let i=0;for(const ps of groups.values()){const p=ps[0],number=++i;L.rectangle([[p.latitude-.01,p.longitude-.01],[p.latitude+.01,p.longitude+.01]],{color:'#1260d9',weight:1,fillOpacity:.07,interactive:false}).addTo(map);L.marker([p.latitude,p.longitude],{title:'Zona '+number+': '+ps.length+' consigli',icon:L.divIcon({className:'fit-pin',html:`<b>${number}</b><span>${ps.length>1?ps.length+' consigli':esc(p.tag)}</span>`,iconSize:[42,42],iconAnchor:[21,21]})}).addTo(map).on('click',()=>{if(editing)return;selected=p.id;$('#fit-post-'+p.id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});document.querySelectorAll('.fit-card').forEach(c=>c.classList.toggle('is-selected',ps.some(p=>c.id==='fit-post-'+p.id)))});}
  map.on('click',e=>{if(editing)area({latitude:e.latlng.lat,longitude:((e.latlng.lng+180)%360+360)%360-180})});drawDraft();
 }catch{if(host.isConnected)host.innerHTML='<p>La mappa non è disponibile. Leggi i consigli nell’elenco.</p>'}}
 function bind(){if(!active())return;events?.abort();events=new AbortController();const signal=events.signal,on=(s,f)=>document.querySelectorAll(s).forEach(b=>b.addEventListener('click',()=>f(b),{signal}));mount();if(!data&&!busy&&!error)load();if(editing&&mine===null&&!mineError)loadMine();
  on('[data-fit-add]',()=>{if(!ctx.get().me?.id)return ctx.login();editing=true;mine=null;mineError='';ctx.render()});on('[data-fit-cancel]',()=>{editing=false;gpsRevision++;ctx.render()});on('[data-fit-mine-retry]',loadMine);on('[data-fit-refresh]',()=>{revision++;busy=false;data=null;error='';ctx.render()});on('[data-fit-clear]',()=>{tag='';revision++;busy=false;data=null;ctx.render()});
  on('[data-fit-search-area]',()=>{if(!map)return;const c=map.getCenter();center=coarseArea(Math.max(-85,Math.min(85,c.lat)),((c.lng+180)%360+360)%360-180);revision++;busy=false;data=null;error='';ctx.render()});
  on('[data-fit-pick]',()=>$('#fit-map')?.scrollIntoView({block:'center'}));on('[data-fit-current]',()=>{const c=map?.getCenter();if(c)area({latitude:c.lat,longitude:c.lng});else area(center)});
  on('[data-fit-gps]',b=>{if(!navigator.geolocation)return ctx.toast('Posizione non disponibile: scegli la zona sulla mappa.');const token=++gpsRevision;b.disabled=true;b.textContent='Cerco la zona…';navigator.geolocation.getCurrentPosition(p=>{if(token!==gpsRevision||!active()||!editing)return;b.disabled=false;b.textContent='Usa la mia zona';if(p.coords.accuracy>5000)return ctx.toast('Posizione troppo incerta. Tocca la zona sulla mappa.');area({latitude:p.coords.latitude,longitude:p.coords.longitude});map?.setView([draft.area.latitude,draft.area.longitude],12)},()=>{if(token!==gpsRevision)return;b.disabled=false;b.textContent='Usa la mia zona';ctx.toast('Posizione non disponibile. Puoi scegliere la zona sulla mappa.')},{enableHighAccuracy:false,timeout:15000,maximumAge:0})});
  on('[data-fit-pin]',b=>{const p=data.posts.find(p=>p.id===b.dataset.fitPin);if(p&&map){map.setView([p.latitude,p.longitude],13);$('#fit-map').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
  on('[data-fit-weather]',()=>ctx.openWeather({...center}));on('[data-fit-ai]',()=>ctx.askAI({...center}));
  on('[data-fit-remove]',b=>ctx.modal('Rimuovi il Fit Check','<p>La zona scompare dalla mappa. Foto, video e commenti restano nel post originale.</p>',async()=>{await ctx.api('fitcheck/remove',{post:b.dataset.fitRemove});data=null;mine=null;ctx.render();ctx.toast('Zona rimossa dalla mappa.')}));
  $('#fit-radius').onchange=e=>{radius=Number(e.target.value);revision++;busy=false;data=null;error='';ctx.render()};$('#fit-filter').onchange=e=>{tag=e.target.value;revision++;busy=false;data=null;error='';ctx.render()};if($('#fit-post'))$('#fit-post').onchange=e=>{selectDraft(e.target.value);ctx.render()};if($('#fit-tag'))$('#fit-tag').onchange=e=>draft.tag=e.target.value;
  $('#fit-publish-form')?.addEventListener('submit',async e=>{e.preventDefault();const status=$('#fit-save-status'),button=$('#fit-save');if(!draft.post||!draft.area){status.textContent='Scegli il contenuto e la zona sulla mappa.';return}button.disabled=true;try{const r=await ctx.api('fitcheck/place',{post:draft.post,...draft.area,tag:draft.tag,consent:$('#fit-consent').checked});center={latitude:r.latitude,longitude:r.longitude};editing=false;data=null;mine=null;ctx.toast('Fit Check aggiunto. Il post resta visibile anche nella community.');if(active())ctx.render()}catch(e){status.textContent=e.message}finally{button.disabled=false}},{signal});
 }
 document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('.fit-workspace video').forEach(v=>v.pause());else if(active()){data=null;ctx.render()}});
 const timer=setInterval(()=>{if(active()&&!document.hidden&&data?.posts.some(p=>p.expires<=Date.now())){data.posts=data.posts.filter(p=>p.expires>Date.now());ctx.render()}},30000);
 return {page,bind,start(id){pendingPost=id;editing=true;mine=null;mineError=''},dispose(){events?.abort();mapRevision++;map?.remove();map=null;draftLayer=null;document.querySelectorAll('.fit-workspace video').forEach(v=>v.pause());if(!active()){revision++;gpsRevision++;busy=false;mineBusy=false;mine=null}},invalidate(){data=null;mine=null}};
}
